File: lib/segment/src/index/field_index/null_index/read_ops.rs, Lines 155-222:

pub(super) fn estimate_cardinality<N: NullIndexRead>(
    null_index: &N,
    condition: &FieldCondition,
) -> Option<CardinalityEstimation> {
    let FieldCondition {
        key,
        r#match: _,
        range: _,
        geo_bounding_box: _,
        geo_radius: _,
        geo_polygon: _,
        values_count: _,
        is_empty,
        is_null,
    } = condition;

    let has_values_flags = null_index.has_values_flags();
    let is_null_flags = null_index.is_null_flags();
    let total_point_count = null_index.total_point_count();

    if let Some(is_empty) = is_empty {
        if *is_empty {
            let has_values_count = has_values_flags.count_trues();
            let estimated = total_point_count.saturating_sub(has_values_count);

            Some(CardinalityEstimation {
                min: 0,
                exp: 2 * estimated / 3,  // <-- PROBLEMATIC HEURISTIC: assumes 1/3 deletion
                max: estimated,
                primary_clauses: vec![PrimaryCondition::from(FieldCondition::new_is_empty(
                    key.clone(),
                    true,
                ))],
            })
        } else {
            let count = has_values_flags.count_trues();
            Some(
                CardinalityEstimation::exact(count).with_primary_clause(PrimaryCondition::from(
                    FieldCondition::new_is_empty(key.clone(), false),
                )),
            )
        }
    } else if let Some(is_null) = is_null {
        if *is_null {
            let count = is_null_flags.count_trues();
            Some(
                CardinalityEstimation::exact(count).with_primary_clause(PrimaryCondition::from(
                    FieldCondition::new_is_null(key.clone(), true),
                )),
            )
        } else {
            let is_null_count = is_null_flags.count_trues();
            let estimated = total_point_count.saturating_sub(is_null_count);

            Some(CardinalityEstimation {
                min: 0,
                exp: 2 * estimated / 3,
                max: estimated,
                primary_clauses: vec![PrimaryCondition::from(FieldCondition::new_is_null(
                    key.clone(),
                    false,
                ))],
            })
        }
    } else {
        None
    }
}

KEY ISSUE: For is_empty=true (lines 176-188), estimation uses exp: 2 * estimated / 3 with comment 'assuming 1/3 of the points are deleted'. In our dataset: has_values_count = 100 (points with kw='red'), total = 200, estimated = 200-100 = 100, exp = 2*100/3 = 66. But observation shows count=25. The heuristic systematically underestimates because it doesn't account for actual data distribution - 100 points without payload 'kw' vs 200 total. The assumption that 1/3 are deleted is invalid for this steady-state indexed dataset.
